counterexample:
-- Although one cannot produce a counterexample (because the queries are equivalent), here is a sample test data set that demonstrates their identical behavior:

INSERT INTO table1 (c1, c2, c3, c4) VALUES (1, 0, 1, '2020-01-01');
INSERT INTO table1 (c1, c2, c3, c4) VALUES (2, 0, 1, '2020-01-01');
-- Group (c4='2020-01-01', c3=1) qualifies because COUNT(DISTINCT c1)=2

INSERT INTO table1 (c1, c2, c3, c4) VALUES (3, 0, 1, '2020-01-02');
-- Group (c4='2020-01-02', c3=1) does not qualify (only one distinct c1), but the overall result will still include 1 because of the first group

INSERT INTO table1 (c1, c2, c3, c4) VALUES (4, 0, 2, '2020-01-01');
INSERT INTO table1 (c1, c2, c3, c4) VALUES (5, 0, 2, '2020-01-01');
-- Group (c4='2020-01-01', c3=2) qualifies because COUNT(DISTINCT c1)=2

-- In both queries, the final output will be the distinct IDs {1,2} sorted appropriately.
-- This sample data confirms that Q1 and Q2 behave identically.

INSERT INTO table1 (c3, c4, c8) VALUES (10, 'S8', 100);
INSERT INTO table1 (c3, c4, c8) VALUES (20, 'IPHONE', 200);

