counterexample:
-- No counterexample exists for the given schema because for any valid set of distinct integers, the minimum absolute difference is always that between two consecutive numbers when sorted.

-- For instance, the following INSERTs are valid test data, but they do not cause Q1 and Q2 to differ:
INSERT INTO table1 (c1) VALUES (1);
INSERT INTO table1 (c1) VALUES (3);
INSERT INTO table1 (c1) VALUES (6);
INSERT INTO table1 (c1) VALUES (10);

-- Both Q1 and Q2 would return 2 (the difference between 1 and 3) in this example.

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 10, 100);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 11, 101);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-01', 12, 102);

-- The following INSERT statements assume that foreign key checking is disabled or deferred so that we can insert an orphaned row in table2.

-- Insert a row into table1 for c3 = 1 (this row will be joined normally)
INSERT INTO table1 (c3, c4, c8) VALUES (1, 'Alpha', 100);

-- Insert two rows into table2 for c3 = 1, both with c6 in the date range
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 10, 101, '2019-02-10', 5, 20);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 20, 102, '2019-03-01', 7, 30);

-- Insert an orphaned row into table2 for c3 = 2 (this c3 does not exist in table1)
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 30, 103, '2019-02-15', 8, 40);

-- When running Q1 and Q2 on this test data:
-- Q1 returns only the row for c3=1 (because it inner joins table1 and ignores the orphaned c3=2 row),
-- while Q2 returns two rows: one for c3=1 and one for c3=2 (with NULL in place of c4 for c3=2).

