/*
Assuming for the counterexample that duplicate login rows on the same day are possible (i.e. ignoring the PK constraint), then the following INSERTs show a difference:

User 1 installs on 2021-01-01 and has two separate logins on 2021-01-02 (day+1).
User 2 installs on 2021-01-01 and has no day+1 login.

For install date 2021-01-01:
 • Q1: For user 1 the JOIN returns 2 rows with day+1 login (CASE sums to 2) and for user 2 the JOIN returns 1 row (CASE sums to 0). The denominator is COUNT(DISTINCT c4)=2, so DAY1_RETENTION = round((2/2),2) = 1.00 (which is anomalously high because user 1 appears to have two day1 events).
 • Q2: The LEFT JOIN returns two rows for user 1 (with non-null B.c2) and one row for user 2 (with null), so COUNT(c2)=2 and COUNT(c4)=3, yielding DAY1_RETENTION = round(2/3,2) = 0.67.

Thus the two queries yield different results.
*/

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2021-01-01', 10, 100);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2021-01-02', 11, 101);
-- The following row is a duplicate day+1 login for user 1 (this would normally violate the PK but is assumed possible for this counterexample)
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2021-01-02', 12, 102);

INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2021-01-01', 20, 200);

-- No counterexample can be produced because under the given schema and standard SQL semantics, Q1 and Q2 are equivalent.
-- For completeness, here are some INSERTs that illustrate the typical cases (all of which yield the same results for Q1 and Q2):

INSERT INTO table3 (c10, c6, c9, c3, c5) VALUES (1, 'A', 10, 100, 'foo');
INSERT INTO table3 (c10, c6, c9, c3, c5) VALUES (2, 'B', 20, 200, 'bar');

-- A row in table1 with c6 = 'RED' (will cause an exclusion in both queries for matching table3 rows)
INSERT INTO table1 (c4, c6, c2) VALUES (10, 'RED', 'x');

-- A row in table1 with a non-matching color
INSERT INTO table1 (c4, c6, c2) VALUES (20, 'BLUE', 'y');

-- A table2 row that qualifies (joins table1 row with 'RED') and references table3.row 1
INSERT INTO table2 (c8, c4, c10, c7, c1) VALUES (100, 10, 1, 'alpha', 1000);

-- A table2 row that does not qualify (joins table1 row but color is not RED) and references table3.row 2
INSERT INTO table2 (c8, c4, c10, c7, c1) VALUES (200, 20, 2, 'beta', 2000);

-- Expected results:
-- For table3 row with c10 = 1: Q1 subquery returns count 1 (because of the qualifying join via table1.c6 = 'RED'), so neither Q1 nor Q2 return it.
-- For table3 row with c10 = 2: Q1 subquery returns count 0 (table1 has 'BLUE', not 'RED'), so both Q1 and Q2 return its c6 value ('B').

-- Running both queries on this data will yield the same result, showing that a counterexample (i.e. a test database where Q1 and Q2 produce different results) cannot be constructed under the given schema.

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'S8', 100);
INSERT INTO table1 (c3, c4, c8) VALUES (3, 'IPHONE', 300);

