INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02 ', 102, 0);

-- Group 2, a single-row group (does not have a qualifying row because there is only the MIN row)
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-02-10', 200, 0);

