INSERT INTO table2 (c2) VALUES (1);

INSERT INTO table1 (c1, c2) VALUES (1, 1);
INSERT INTO table1 (c1, c2) VALUES (2, NULL);

-- In this database, the subquery in Q1 returns 1 (since there is exactly one distinct non-null value in table2) and each row in table1 yields either 1 (if c2 is non-null) or 0 (if c2 is NULL).
-- Thus Q1 returns c1 = 1 while Q2, which compares 1 to the computed COUNT(DISTINCT c2) in each group, also returns c1 = 1.

-- To get a divergence you would need to allow duplicates in table2 or multiple rows per c1 in table1. For example, if table2 could contain duplicate values then:
--   INSERT INTO table2 (c2) VALUES (1);
--   INSERT INTO table2 (c2) VALUES (1);
-- would cause Q2's COUNT(c2) to be 2 while Q1's COUNT(DISTINCT c2) would remain 1. However, such an insert would violate the primary key constraint on table2.

