counterexample:
-- Group 1: c4 = 1. We insert three rows. The minimum date is '2020-01-01'.
-- We insert two rows for '2020-01-02' (duplicate qualifying date) so that Q1 will count 2 for this group.
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 10, 100);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 20, 200);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 30, 300);

-- Group 2: c4 = 2. Normal group, one qualifying row.
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-01', 40, 400);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2020-01-02', 50, 500);

-- Explanation of expected differences:
-- For group 1, TEMP yields MIN_DATE = '2020-01-01'. The join with table1 for c4=1 finds three rows, two of which have c2 = '2020-01-02', so Q1's numerator gets 2 for this group.
-- For group 2, the join gives one match (the row dated '2020-01-02').
-- Thus, Q1 computes a total numerator of 3 over 2 groups, yielding 1.50 (after rounding).
-- In Q2, the window function on group 1 gives the rank‑1 row as the one with '2020-01-01' and both rows with '2020-01-02' receive rank 2 (a tie). When joined on T1.RK=1 and T2.RK=2, group 1 is counted only once (via COUNT(DISTINCT c4)). Similarly, group 2 counts once. Hence Q2 returns 1.00.
-- This discrepancy shows that the two queries are not equivalent under the scenario of duplicates.

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2000-01-01', 100, 1);
-- The following row would be disallowed by the primary key, but imagine for a moment that duplicates were allowed:
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2000-01-01', 100, 2);

-- Additionally, to show non‐ambiguous behavior for another group, we add a normal group:
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2001-01-01', 200, 3);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2001-02-01', 300, 4);

