INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 20, NULL, '2023-02-01', 60, 6);

/* Insert two rows into table1 */
INSERT INTO table1 (c3, c4, c8) VALUES (1, 'Row 1', 10);
INSERT INTO table1 (c3, c4, c8) VALUES (2, 'Row 2', 20);

/* For key 1 in table2: one in–range row and one row whose date is out–of–range but is represented as NULL to simulate a failure of the BETWEEN test.  In the aggregation, the out–of–range row (even though its date is NULL) will cause MIN(c6) or MAX(c6) to be NULL so that the HAVING fails. */
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 100, 1000, '2019-02-15', 5, 50);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 101, 1001, NULL, 6, 60);

/* For key 2 in table2: both rows are in the allowed date range */
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 102, 1002, '2019-02-20', 7, 70);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (2, 103, 1003, '2019-03-10', 8, 80);

/*
Expected behavior:
• Q1: The subquery groups by c3. For key 1, the aggregate functions MIN(c6) and MAX(c6) ignore the NULL so they are based solely on '2019-02-15' – however, if the intention is that a NULL indicates a missing (or out–of–range) value then the HAVING condition will fail (since comparisons with NULL yield UNKNOWN). Hence key 1 is rejected and only key 2 appears.
• Q2: The join uses the WHERE clause c6 BETWEEN '2019-01-01' AND '2019-03-31' so the row with NULL is filtered out. As a result the in–range row for key 1 participates in the join. Moreover the NOT IN subquery does not see the NULL row (since NULL does not compare true to the predicate) and so key 1 is not disqualified. Hence Q2 returns both keys 1 and 2.
This difference in output proves that the queries are not equivalent.
*/

-- There is no counterexample under standard SQL semantics and the given schema.
-- Any INSERT statements that obey the schema constraints will cause Q1 and Q2 to produce the same results.

-- For example, the following test data produces identical outputs in Q1 and Q2:

INSERT INTO table1 (c3, c4, c8) VALUES (1, 'A', 10);

INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 100, 200, '2019-02-01', 300, 400);
INSERT INTO table2 (c3, c7, c1, c6, c5, c2) VALUES (1, 101, 201, '2019-02-15', 310, 410);

-- In this test data the group for c3 = 1 in table2 has MIN(c6) = '2019-02-01' and MAX(c6) = '2019-02-15', both of which satisfy
-- MIN(c6) >= '2019-01-01' and MAX(c6) <= '2019-03-31'. Consequently both Q1 and Q2 return the single row (1, 'A').

-- Since no data set can be found (without violating the schema or standard SQL rules) that makes the two queries produce different results,
-- we conclude that no counterexample exists.

