-- Insert a row into table3 with a NULL value for c10 (assuming our SQL dialect allows it even though c10 is declared as PRIMARY KEY)
INSERT INTO table3 (c10, c6, c9, c3, c5) VALUES (NULL, 'NullKeyRow', 0, 0, 'test');

-- Insert a valid row in table3 whose key is not null to show normal behavior
INSERT INTO table3 (c10, c6, c9, c3, c5) VALUES (1, 'NormalRow', 0, 0, 'test');

-- Insert a row into table1 and table2 such that table3.c10 = 1 has an associated red row
INSERT INTO table1 (c4, c6, c2) VALUES (10, 'RED', 'dummy');
INSERT INTO table2 (c8, c4, c10, c7, c1) VALUES (100, 10, 1, 'dummy', 0);

/*
Evaluation:
• For the row with c10 = 1, Q1’s subquery will find a matching row (because 1 = 1) and the count will be > 0, so Q1 does not return this row. Q2’s subquery will include 1, and thus the row is filtered out.
• For the row with c10 = NULL, Q1’s correlated subquery returns COUNT(*) = 0 (since no row in table2 can satisfy O.c10 = NULL), so Q1 returns it. However, in Q2 the outer condition becomes NULL NOT IN (<...>); since NULL compared with any value yields UNKNOWN, the row is not returned.
Thus Q1 returns the NULL‐key row while Q2 does not, exposing the nonequivalence.*/

