/*
Assume that for the purposes of this counterexample the PK constraint is not enforced so that duplicates are allowed.
The following INSERT statements set up the test data.
*/

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 10, 100);
-- Two rows for 2020-01-02 for c4 = 1 (duplicate next–day rows)
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 20, 200);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-02', 30, 300);

