-- For group 2 (c4 = 2):
INSERT INTO table1 (c4, c2, c1, c3) VALUES (2, '2023-01-03', 40, 400);

-- In a system where duplicate rows (for group 1 on '2023-01-02') were allowed, Q1 would sum a numerator of 2 (because group 1 has two qualifying rows) and a denominator of 2 (two groups), yielding 1.00, whereas Q2 would count group 1 only once and yield 0.50.

