INSERT INTO table1 (c4, c3, c2, c1, EXTRA) VALUES (2, 200, '2019-07-04', 'REPORT', 'B');
INSERT INTO table1 (c4, c3, c2, c1, EXTRA) VALUES (3, 100, '2019-07-04', 'REPORT', 'A');

