-- The following INSERTs illustrate the counterexample data if the primary key restriction were not in effect (i.e. if duplicate installs on the same day were allowed).
-- For example, suppose we relax the PK constraint. Then user 1 logs in twice on the install day '2020-01-01' and once on the next day '2020-01-02'. User 2 logs in normally.

INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 10, 100);
INSERT INTO table1 (c4, c2, c1, c3) VALUES (1, '2020-01-01', 11, 101);  -- duplicate install-day row for user 1
